(1086028, 132480, 28364, '<td valign="top">I like.</td>', 'I like.', '2005-01-02 01:16:19.000000', NULL, 1),
(1086029, 132461, 30861, '<td valign="top">Nice work. A little too blocked up in the trees; what we call a zone 2, where a strong 3 would show a hint of texture and help things along. Image is slightly out of square, too. About a degree of ccw rotation would take care of that nicely.</td>', 'Nice work. A little too blocked up in the trees; what we call a zone 2, where a strong 3 would show a hint of texture and help things along. Image is slightly out of square, too. About a degree of ccw rotation would take care of that nicely.', '2005-01-02 01:17:06.000000', NULL, 1),
(1086030, 132316, 30861, '<td valign="top">nice montage effect. I wish the skin/shoe tones were a little warmer...</td>', 'nice montage effect. I wish the skin/shoe tones were a little warmer...', '2005-01-02 01:18:04.000000', NULL, 1),
(1086031, 132381, 30861, '<td valign="top">I''m not sure how "simple" what you''re seeing is, here. Nice shot, though. And a fine resolution.</td>', 'I''m not sure how "simple" what you''re seeing is, here. Nice shot, though. And a fine resolution.', '2005-01-02 01:18:55.000000', NULL, 1),
(1086032, 132398, 30861, '<td valign="top">A lot of life here, heady brew of a picture. I''m EXTREMELY bothered by the (apparently) desaturated, portly figure to the left. He''s a total eyetrap. I''d have burned him into submission for sure.</td>', 'A lot of life here, heady brew of a picture. I''m EXTREMELY bothered by the (apparently) desaturated, portly figure to the left. He''s a total eyetrap. I''d have burned him into submission for sure.', '2005-01-02 01:20:37.000000', NULL, 1),
(1086033, 132218, 30861, '<td valign="top">Technically very nice, and a good "storyboard", but it leaves me with a sense that it''s all too "pat". Be nice if the cuff were ironed, too :-)</td>', 'Technically very nice, and a good "storyboard", but it leaves me with a sense that it''s all too "pat". Be nice if the cuff were ironed, too :-)', '2005-01-02 01:21:50.000000', NULL, 1),
(1086034, 132015, 26773, '<td valign="top">Thats awesome</td>', 'Thats awesome', '2005-01-02 01:21:53.000000', NULL, 1),
