(1086197, 132127, 14656, '<td valign="top">If Ansel Adams shot in color, I think it would''ve looked like this.</td>', 'If Ansel Adams shot in color, I think it would''ve looked like this.', '2005-01-02 03:07:42.000000', NULL, 1),
(1086199, 132424, 14656, '<td valign="top">What a great resolution and a photo to go with it!</td>', 'What a great resolution and a photo to go with it!', '2005-01-02 03:08:57.000000', NULL, 1),
(1086200, 132470, 14656, '<td valign="top">Excellent composition and well executed photo and idea. My pick for top10!</td>', 'Excellent composition and well executed photo and idea. My pick for top10!', '2005-01-02 03:09:37.000000', NULL, 1),
(1086202, 132168, 10658, '<td valign="top">Without the title I get a "Reach for the stars" message from this photo, that''s great!  Most of the photos are hard to judge because they only fit because of their titles (which isn''t in the spirit of the competition in my opinion).  On the other hand, I don''t like the rest of the wires crossing the photo below the star.  Personal preference probably.  Going with a 7</td>', 'Without the title I get a "Reach for the stars" message from this photo, that''s great!  Most of the photos are hard to judge because they only fit because of their titles (which isn''t in the spirit of the competition in my opinion).  On the other hand, I don''t like the rest of the wires crossing the photo below the star.  Personal preference probably.  Going with a 7', '2005-01-02 03:13:10.000000', NULL, 1),
(1086203, 132283, 7438, '<td valign="top">The steel bars are a nice framing element and the hair is great -- it''d be so much stronger in B/W though</td>', 'The steel bars are a nice framing element and the hair is great -- it''d be so much stronger in B/W though', '2005-01-02 03:13:58.000000', NULL, 1),
(1086204, 132169, 7438, '<td valign="top">Nice and clean I suppose, although including the whole bottle would be better I think</td>', 'Nice and clean I suppose, although including the whole bottle would be better I think', '2005-01-02 03:15:42.000000', NULL, 1),
(1086205, 132069, 13749, '<td valign="top">very clever and unique and i love the selective desat here.</td>', 'very clever and unique and i love the selective desat here.', '2005-01-02 03:15:51.000000', NULL, 1),
(1086206, 132344, 13749, '<td valign="top">curious as to whether you chose this for the challenge or took it for the challenge ;) - either way, this very interesting composition and use of colors works well.</td>', 'curious as to whether you chose this for the challenge or took it for the challenge ;) - either way, this very interesting composition and use of colors works well.', '2005-01-02 03:17:32.000000', NULL, 1),
(1086207, 132424, 17877, '<td valign="top">hahahahaha</td>', 'hahahahaha', '2005-01-02 03:17:39.000000', NULL, 1),
(1086208, 131950, 13749, '<td valign="top">does this mean you''re having no regrets by getting rid of the alcohol or by not caring and drinking it all?  hehe, either way i like the shot.</td>', 'does this mean you''re having no regrets by getting rid of the alcohol or by not caring and drinking it all?  hehe, either way i like the shot.', '2005-01-02 03:18:37.000000', NULL, 1),
(1086210, 132364, 7438, '<td valign="top">Now that''s a fun version -- definitely the best I''ve seen of the ''quit smoking'' pictures yet. B/W would work better for it though, IMO</td>', 'Now that''s a fun version -- definitely the best I''ve seen of the ''quit smoking'' pictures yet. B/W would work better for it though, IMO', '2005-01-02 03:20:07.000000', NULL, 1),
(1086211, 132215, 13749, '<td valign="top">that''s a goofy place to store them - how is anyone gonna see them unless you have that door open all the time??!  jk - creative twist - good luck to you in ''05 :)</td>', 'that''s a goofy place to store them - how is anyone gonna see them unless you have that door open all the time??!  jk - creative twist - good luck to you in ''05 :)', '2005-01-02 03:20:12.000000', NULL, 1),
(1086215, 132403, 25787, '<td valign="top">Congratulations!</td>', 'Congratulations!', '2005-01-02 03:24:31.000000', NULL, 1),
(1086217, 132015, 13749, '<td valign="top">lol.  great on humor and creativity - a very good find, too!  not sure about the resolution, but who am i to judge whether it''s appropriate or not (for all i know, you have 10,000 pics of a flag and need to stop!).  great job.</td>', 'lol.  great on humor and creativity - a very good find, too!  not sure about the resolution, but who am i to judge whether it''s appropriate or not (for all i know, you have 10,000 pics of a flag and need to stop!).  great job.', '2005-01-02 03:25:18.000000', NULL, 1),
(1086218, 132210, 13749, '<td valign="top">judging by your arms, i think you''re already using bigger weights.. either that, or i got screwed with the genetics!  nice, clean, crisp shot with good tones and composition.  not sure if i think that your ny resolution is the best, but who am i to judge (maybe you got injured and have been going light lately?) - great shot.</td>', 'judging by your arms, i think you''re already using bigger weights.. either that, or i got screwed with the genetics!  nice, clean, crisp shot with good tones and composition.  not sure if i think that your ny resolution is the best, but who am i to judge (maybe you got injured and have been going light lately?) - great shot.', '2005-01-02 03:26:00.000000', NULL, 1),
(1086219, 132223, 13749, '<td valign="top">this should be my resolution.  great b&amp;w and i think the frame works well here.</td>', 'this should be my resolution.  great b&w and i think the frame works well here.', '2005-01-02 03:28:36.000000', NULL, 1),
(1086221, 132044, 7438, '<td valign="top">More night shots definitely, but less colored borders! This would look pretty slick without the border, and another suggestion would be to include either more water or more sky, to avoid placing the horizon so close to the middle of the frame.</td>', 'More night shots definitely, but less colored borders! This would look pretty slick without the border, and another suggestion would be to include either more water or more sky, to avoid placing the horizon so close to the middle of the frame.', '2005-01-02 03:30:08.000000', NULL, 1),
(1086223, 132449, 13749, '<td valign="top">very interesting style and choice for the hills in the distance.  picture seems to go from dark to bright, which seems to help lead my eyedown ''the right path''.  good work.</td>', 'very interesting style and choice for the hills in the distance.  picture seems to go from dark to bright, which seems to help lead my eyedown ''the right path''.  good work.', '2005-01-02 03:31:04.000000', NULL, 1),
(1086225, 132467, 10658, '<td valign="top">Okay,  I understand wanting to get a ribbon but oh my god...obviously it''s great technically, the shock factor draws horrified viewers in so that''s something.  I''ll give you a 10, but next time you need to get rid of a wad of 20''s keep my name in mind, ''kay?</td>', 'Okay,  I understand wanting to get a ribbon but oh my god...obviously it''s great technically, the shock factor draws horrified viewers in so that''s something.  I''ll give you a 10, but next time you need to get rid of a wad of 20''s keep my name in mind, ''kay?', '2005-01-02 03:32:24.000000', NULL, 1),
(1086226, 132364, 13749, '<td valign="top">even though there''s another ''kick the habit'', i think this is very interesting and well executed take on an extremely popular resolution.  great composition and color.</td>', 'even though there''s another ''kick the habit'', i think this is very interesting and well executed take on an extremely popular resolution.  great composition and color.', '2005-01-02 03:32:30.000000', NULL, 1),
(1086227, 132288, 23458, '<td valign="top">Well this is a gorgeous image, great DOF and lighting. The challenge link is a little tenuous - I''d say the beauty in these flowers is immediately apparent, and it does seem like the title and the image are just thrown together in the hopes of meeting the challenge. It is however, a new year, and in the spirit of the holiday season I''ll give you the benefit of the doubt and a 7 for the obvious technical skill displayed here.</td>', 'Well this is a gorgeous image, great DOF and lighting. The challenge link is a little tenuous - I''d say the beauty in these flowers is immediately apparent, and it does seem like the title and the image are just thrown together in the hopes of meeting the challenge. It is however, a new year, and in the spirit of the holiday season I''ll give you the benefit of the doubt and a 7 for the obvious technical skill displayed here.', '2005-01-02 03:32:47.000000', NULL, 1),
(1086228, 132157, 13749, '<td valign="top">good resolution.  hope you don''t get any bad comments on this, cuz it really is an interesting picture (i could imagine some "this is a stretch to fit the challenge" comments, but i prefer to view this challenge with a very wide mind and level of interpretation).</td>', 'good resolution.  hope you don''t get any bad comments on this, cuz it really is an interesting picture (i could imagine some "this is a stretch to fit the challenge" comments, but i prefer to view this challenge with a very wide mind and level of interpretation).', '2005-01-02 03:33:36.000000', NULL, 1),
(1086229, 131754, 10658, '<td valign="top">Great message, says it all without needing the title to get by so you''ll get a 10 from me.</td>', 'Great message, says it all without needing the title to get by so you''ll get a 10 from me.', '2005-01-02 03:33:58.000000', NULL, 1),
(1086231, 132090, 22011, '<td valign="top">Lovely pet photo, but I find the reflections in the eyes a little off-putting...  Great choice of shallow DOF.</td>', 'Lovely pet photo, but I find the reflections in the eyes a little off-putting...  Great choice of shallow DOF.', '2005-01-02 03:34:20.000000', NULL, 1),
(1086232, 131762, 13749, '<td valign="top">great portrait.  lighting could be slightly more contrasty/dramatic in order to emphasize the good/bad halves (that i assume you are trying to convey), but that''s only a matter of personal taste.</td>', 'great portrait.  lighting could be slightly more contrasty/dramatic in order to emphasize the good/bad halves (that i assume you are trying to convey), but that''s only a matter of personal taste.', '2005-01-02 03:35:39.000000', NULL, 1),
(1086233, 132069, 7438, '<td valign="top">Ooh, ultra thin. You stud. <br/> <br/>Anyway, this is all well and good, almost looks like a pro product shot, but if I had to make changes I would place the wrapper a bit lower in the frame and exaggerate the negative space above</td>', 'Ooh, ultra thin. You stud.  Anyway, this is all well and good, almost looks like a pro product shot, but if I had to make changes I would place the wrapper a bit lower in the frame and exaggerate the negative space above', '2005-01-02 03:36:51.000000', NULL, 1),
(1086234, 131736, 14656, '<td valign="top">Let''s see... babies, post-its, and forgetting to turn on the screen saver? Perhaps removing the objects from their natural surrounding for photographic purposes would be better. I''m guessing it''s really beer, peanuts, and poker? Still unsure.<br/> <br/>Edit&gt;&gt;<br/>I saw your post in the resolutions thread, didn''t even notice the ashtray. You should really edit your post.</td>', 'Let''s see... babies, post-its, and forgetting to turn on the screen saver? Perhaps removing the objects from their natural surrounding for photographic purposes would be better. I''m guessing it''s really beer, peanuts, and poker? Still unsure. Edit>>I saw your post in the resolutions thread, didn''t even notice the ashtray. You should really edit your post.', '2005-01-02 03:37:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1086235, 132162, 24982, '<td valign="top">neat. it''s good that you got the pack of smokes to spin perfectly like that.</td>', 'neat. it''s good that you got the pack of smokes to spin perfectly like that.', '2005-01-02 03:38:04.000000', NULL, 1),
(1086236, 132203, 22011, '<td valign="top">I can see you were going for a ''moody'' look this this shot, but I think the image as a whole came out a little dark.  Enjoy the walking. :-).</td>', 'I can see you were going for a ''moody'' look this this shot, but I think the image as a whole came out a little dark.  Enjoy the walking. :-).', '2005-01-02 03:39:08.000000', NULL, 1),
