(1086665, 131950, 24846, '<td valign="top">Nice desat. Like the shadows and dof. A little bit to bright  on top of image. Good luck and HNY.</td>', 'Nice desat. Like the shadows and dof. A little bit to bright  on top of image. Good luck and HNY.', '2005-01-02 11:35:48.000000', NULL, 1),
(1086666, 132330, 4226, '<td valign="top">I seem to recognise her.. is that your daughter parrothead ? ( please don''t mind if i am wrong :D )<br/>Great angle on this shot and a very nice color balance. It gives a very soothing effect.</td>', 'I seem to recognise her.. is that your daughter parrothead ? ( please don''t mind if i am wrong :D )Great angle on this shot and a very nice color balance. It gives a very soothing effect.', '2005-01-02 11:36:25.000000', NULL, 1),
(1086667, 131828, 24846, '<td valign="top">Nice concept of choices. Like the use of primary colors. Good luck and HNY.</td>', 'Nice concept of choices. Like the use of primary colors. Good luck and HNY.', '2005-01-02 11:38:19.000000', NULL, 1),
(1086668, 132090, 10080, '<td valign="top">Sweet soft shot! The reflection in the eyes bugs me a bit? But well done...8</td>', 'Sweet soft shot! The reflection in the eyes bugs me a bit? But well done...8', '2005-01-02 11:39:20.000000', NULL, 1),
(1086669, 132379, 10080, '<td valign="top">Actually a very intriguing shot! 7</td>', 'Actually a very intriguing shot! 7', '2005-01-02 11:40:51.000000', NULL, 1),
(1086671, 132378, 24846, '<td valign="top">Very nice negative space image. Love the softness the grass and tres bring in. All that white canmake for a difficult exposure but you did a great job. One of may favorites thus far.Good luck and HNY.</td>', 'Very nice negative space image. Love the softness the grass and tres bring in. All that white canmake for a difficult exposure but you did a great job. One of may favorites thus far.Good luck and HNY.', '2005-01-02 11:41:01.000000', NULL, 1),
(1086674, 132244, 21714, '<td valign="top">Nice lighting and composition. There are places where the it looks a bit odd like around the shoulders, but I think it''s a great image. Well done.</td>', 'Nice lighting and composition. There are places where the it looks a bit odd like around the shoulders, but I think it''s a great image. Well done.', '2005-01-02 11:42:02.000000', NULL, 1),
(1086676, 131762, 21714, '<td valign="top">Great portrait. Beautiful photography. Excellent.</td>', 'Great portrait. Beautiful photography. Excellent.', '2005-01-02 11:43:33.000000', NULL, 1),
(1086677, 131730, 24846, '<td valign="top">Nice composition Like how the few colors against the white just pop out. Well balanced crop. Maybe a bit sharper focus on the JD label or the glass. Good luck and HNY.</td>', 'Nice composition Like how the few colors against the white just pop out. Well balanced crop. Maybe a bit sharper focus on the JD label or the glass. Good luck and HNY.', '2005-01-02 11:43:38.000000', NULL, 1),
