(1086680, 132466, 10080, '<td valign="top">Its a nice shot....just missing that black. It would have given it more punch. Still a 7</td>', 'Its a nice shot....just missing that black. It would have given it more punch. Still a 7', '2005-01-02 11:44:58.000000', NULL, 1),
(1086683, 132424, 21714, '<td valign="top">Way to start an exciting family :) Great idea behind a nicely executed image. Well done.</td>', 'Way to start an exciting family :) Great idea behind a nicely executed image. Well done.', '2005-01-02 11:45:39.000000', NULL, 1),
