INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1086686, 132245, 10080, '<td valign="top">Actually the best of the dog shots that I have seen, and one of the better entries in this contest! I like the tonal range, and the eyes really add punch! Welldone! 9</td>', 'Actually the best of the dog shots that I have seen, and one of the better entries in this contest! I like the tonal range, and the eyes really add punch! Welldone! 9', '2005-01-02 11:48:03.000000', NULL, 1),
(1086689, 132470, 21714, '<td valign="top">You have done a good bit work on it and the idea works in the image. But I can''t fail to notice the not so clean looking fork. I think that bit takes away from a rather clinically clean image.</td>', 'You have done a good bit work on it and the idea works in the image. But I can''t fail to notice the not so clean looking fork. I think that bit takes away from a rather clinically clean image.', '2005-01-02 11:48:57.000000', NULL, 1),
(1086690, 131911, 21714, '<td valign="top">I like the compositon and the colours very much. It looks a tad bit oversharpened to me. Otherwise, a nice image.</td>', 'I like the compositon and the colours very much. It looks a tad bit oversharpened to me. Otherwise, a nice image.', '2005-01-02 11:49:55.000000', NULL, 1),
(1086694, 132424, 10080, '<td valign="top">great take! 8</td>', 'great take! 8', '2005-01-02 11:51:31.000000', NULL, 1),
(1086695, 132267, 10080, '<td valign="top">Nice clean shot! 8</td>', 'Nice clean shot! 8', '2005-01-02 11:52:19.000000', NULL, 1),
(1086697, 131810, 10080, '<td valign="top">Looks good! Yum! 8</td>', 'Looks good! Yum! 8', '2005-01-02 11:53:07.000000', NULL, 1),
(1086698, 132369, 24846, '<td valign="top">Looking a bit gaunt  today. Nice exposure work. It all blends well, I wish there wasn''t a cast over the corner in your right eye. I like how the image tells us life is short enough. Everything in moderation and enjoy. Good luck and HNY.</td>', 'Looking a bit gaunt  today. Nice exposure work. It all blends well, I wish there wasn''t a cast over the corner in your right eye. I like how the image tells us life is short enough. Everything in moderation and enjoy. Good luck and HNY.', '2005-01-02 11:53:21.000000', NULL, 1),
(1086700, 132461, 21714, '<td valign="top">It looks a bit overcooked during processing. The detail and textures are lost and it''s all smudged up.  It does look like you have tried to get rid of some noise and ended up going a bit too far for it to look natural.</td>', 'It looks a bit overcooked during processing. The detail and textures are lost and it''s all smudged up.  It does look like you have tried to get rid of some noise and ended up going a bit too far for it to look natural.', '2005-01-02 11:55:00.000000', NULL, 1),
(1086702, 132015, 24846, '<td valign="top">Very cool and creative flag abstract. Well balanced crop. Good luck and HNY.</td>', 'Very cool and creative flag abstract. Well balanced crop. Good luck and HNY.', '2005-01-02 11:55:29.000000', NULL, 1),
(1086703, 132364, 24846, '<td valign="top">Nice use of negative space. Great crop. Good luck and HNY</td>', 'Nice use of negative space. Great crop. Good luck and HNY', '2005-01-02 11:56:16.000000', NULL, 1),
(1086708, 132370, 21714, '<td valign="top">Very creative. I like your different approach and presentation. I can''t be sure of what your actual concept is, but if it means that you don''t like your shadow anymore or you want to change your shadow or reflection, I think you are very clever in taking that approach and creating this image.</td>', 'Very creative. I like your different approach and presentation. I can''t be sure of what your actual concept is, but if it means that you don''t like your shadow anymore or you want to change your shadow or reflection, I think you are very clever in taking that approach and creating this image.', '2005-01-02 11:58:29.000000', NULL, 1),
(1086716, 132465, 21714, '<td valign="top">Great B&amp;W. But I do find the image a bit too cluttered. I think you have tried to say too much with this image. It might not be a setup, but as it is, it''s hard to understand (at least for me).<br/>Well done on the monochrome.</td>', 'Great B&W. But I do find the image a bit too cluttered. I think you have tried to say too much with this image. It might not be a setup, but as it is, it''s hard to understand (at least for me).Well done on the monochrome.', '2005-01-02 12:02:52.000000', NULL, 1),
(1086719, 132294, 24183, '<td valign="top">I think one problem is that there are too many things to focus on.  I''m not sure if people will like the post editing.</td>', 'I think one problem is that there are too many things to focus on.  I''m not sure if people will like the post editing.', '2005-01-02 12:06:38.000000', NULL, 1),
(1086721, 132369, 21714, '<td valign="top">One of the scariest images I have seen on DPC :) I am finding it hard to even look at it. Because of the overlay of the skull, even the eyes look all creepy and it goes down deep into your system and finds a fear that I would not like to address soon. <br/>I think it''s a very powerful image. Well done.</td>', 'One of the scariest images I have seen on DPC :) I am finding it hard to even look at it. Because of the overlay of the skull, even the eyes look all creepy and it goes down deep into your system and finds a fear that I would not like to address soon. I think it''s a very powerful image. Well done.', '2005-01-02 12:07:10.000000', NULL, 1),
(1086722, 132221, 24183, '<td valign="top">The left flame is slightly blown out, other than that I like it.</td>', 'The left flame is slightly blown out, other than that I like it.', '2005-01-02 12:07:26.000000', NULL, 1),
(1086728, 132330, 24183, '<td valign="top">I like the overhead shot</td>', 'I like the overhead shot', '2005-01-02 12:11:03.000000', NULL, 1),
(1086729, 132447, 24183, '<td valign="top">very cool</td>', 'very cool', '2005-01-02 12:11:56.000000', NULL, 1),
(1086730, 132471, 21714, '<td valign="top">Do colour your world, but if you go to this extent I think you''d be kept away from the public :) <br/>I like your idea and combination here, but I can''t directly relate it to anything.  There''s a bit of a depth of field issue here, I think. The yellow, orange and green to an extent falls a bit the focus point and doesn''t have the same amout of sharpness as teh red and purple.  I think it would have worked better if the focus point was on yellow and then the shallow DOF had it''s effect on whatever else. The way it is now, it makes me want to avoid that area.</td>', 'Do colour your world, but if you go to this extent I think you''d be kept away from the public :) I like your idea and combination here, but I can''t directly relate it to anything.  There''s a bit of a depth of field issue here, I think. The yellow, orange and green to an extent falls a bit the focus point and doesn''t have the same amout of sharpness as teh red and purple.  I think it would have worked better if the focus point was on yellow and then the shallow DOF had it''s effect on whatever else. The way it is now, it makes me want to avoid that area.', '2005-01-02 12:12:51.000000', NULL, 1),
