(1087537, 132364, 22479, '<td valign="top">Clean presentation and quite effective! Nice use of negative space.</td>', 'Clean presentation and quite effective! Nice use of negative space.', '2005-01-02 20:51:28.000000', NULL, 1),
(1087541, 132316, 22479, '<td valign="top">Cool use of motion blur, executed properly and to good effect. Selective desat and toning done aesthetically. It appears you put a lot of thoughtful effort into this and it shows. Well done.</td>', 'Cool use of motion blur, executed properly and to good effect. Selective desat and toning done aesthetically. It appears you put a lot of thoughtful effort into this and it shows. Well done.', '2005-01-02 20:55:48.000000', NULL, 1),
(1087543, 132330, 22479, '<td valign="top">I like the toning and the angle here, very tastefully executed. DOF appears to fairly wide which I think works well given the perspective.</td>', 'I like the toning and the angle here, very tastefully executed. DOF appears to fairly wide which I think works well given the perspective.', '2005-01-02 20:57:10.000000', NULL, 1),
(1087560, 132044, 1531, '<td valign="top">Typical, but still good, "city by night" photo</td>', 'Typical, but still good, "city by night" photo', '2005-01-02 21:09:27.000000', NULL, 1),
(1087584, 132470, 22479, '<td valign="top">Remarkable lighting in this photograph. I like how the embossed design in the plate show itself so subtly. Good composition and fitting for this challenge.</td>', 'Remarkable lighting in this photograph. I like how the embossed design in the plate show itself so subtly. Good composition and fitting for this challenge.', '2005-01-02 21:28:13.000000', NULL, 1),
(1087588, 132424, 3306, '<td valign="top">Have fun now because once you have the family you will be too tired!! Clever picture. Good luck.</td>', 'Have fun now because once you have the family you will be too tired!! Clever picture. Good luck.', '2005-01-02 21:30:49.000000', NULL, 1),
(1087591, 132267, 3306, '<td valign="top">Good job. I like the action in the backround. It tells the viewer there is a story behind the picture. Well done.</td>', 'Good job. I like the action in the backround. It tells the viewer there is a story behind the picture. Well done.', '2005-01-02 21:32:36.000000', NULL, 1),
(1087594, 131883, 3306, '<td valign="top">Comical and entertaining. I like the colorful backround. Nicely photographed as well. Good job</td>', 'Comical and entertaining. I like the colorful backround. Nicely photographed as well. Good job', '2005-01-02 21:34:09.000000', NULL, 1),
(1087596, 132044, 3306, '<td valign="top">What an awesome picture. I love the lines and reflections in the water. Looks like a postcard.</td>', 'What an awesome picture. I love the lines and reflections in the water. Looks like a postcard.', '2005-01-02 21:35:03.000000', NULL, 1),
(1087597, 132127, 22479, '<td valign="top">Please, shoot away, and allow us to view the beauty of your talent through your eyes. :-) 10</td>', 'Please, shoot away, and allow us to view the beauty of your talent through your eyes. :-) 10', '2005-01-02 21:36:07.000000', NULL, 1),
(1087599, 131769, 3306, '<td valign="top">Wonderful silhouette. Very effective negative space.  I like your picture very much. Great job.</td>', 'Wonderful silhouette. Very effective negative space.  I like your picture very much. Great job.', '2005-01-02 21:36:41.000000', NULL, 1),
(1087603, 132464, 3306, '<td valign="top">Great imagery. Very creative. You have a good imagination and display it nicely in your picture.</td>', 'Great imagery. Very creative. You have a good imagination and display it nicely in your picture.', '2005-01-02 21:37:55.000000', NULL, 1),
(1087608, 132245, 3306, '<td valign="top">Look who''s Alpha. I don''t think you have a choice. Great shot. Excellent focus. I love the eyes.</td>', 'Look who''s Alpha. I don''t think you have a choice. Great shot. Excellent focus. I love the eyes.', '2005-01-02 21:39:06.000000', NULL, 1),
(1087611, 132315, 3306, '<td valign="top">Well done leading lines. I wonder what is around the bend on your path!</td>', 'Well done leading lines. I wonder what is around the bend on your path!', '2005-01-02 21:40:05.000000', NULL, 1),
(1087613, 131899, 22479, '<td valign="top">I love everything about this photograph except for one issue: the DOF was a bit narrow and the focus is midway along the snout, resulting in soft facial features.<br/></td>', 'I love everything about this photograph except for one issue: the DOF was a bit narrow and the focus is midway along the snout, resulting in soft facial features.', '2005-01-02 21:41:04.000000', NULL, 1),
(1087616, 132127, 3306, '<td valign="top">Beautiful shot. Looks like a painting. I think I would be taking alot of shots of this panorama so that I could enjoy it again and again! Great job.</td>', 'Beautiful shot. Looks like a painting. I think I would be taking alot of shots of this panorama so that I could enjoy it again and again! Great job.', '2005-01-02 21:42:19.000000', NULL, 1),
(1087617, 132181, 22479, '<td valign="top">Not quite sure how you achieved this effect, but it''s quite unique and aesthetically pleasing. Graceful pose and wonderful exposure and focus. 8</td>', 'Not quite sure how you achieved this effect, but it''s quite unique and aesthetically pleasing. Graceful pose and wonderful exposure and focus. 8', '2005-01-02 21:42:30.000000', NULL, 1),
(1087618, 131769, 22479, '<td valign="top">Breathtaking vista. Nice play of light and shadow. Stunning composition! 9</td>', 'Breathtaking vista. Nice play of light and shadow. Stunning composition! 9', '2005-01-02 21:42:39.000000', NULL, 1),
(1087620, 132340, 22479, '<td valign="top">Breathtaking vista, and a magical moment captured for our viewing pleasure. I would not change anything in this composition. 9</td>', 'Breathtaking vista, and a magical moment captured for our viewing pleasure. I would not change anything in this composition. 9', '2005-01-02 21:42:48.000000', NULL, 1),
(1087621, 132015, 22479, '<td valign="top">Wow...remarkable composition and imagination. Excellent eye! 8</td>', 'Wow...remarkable composition and imagination. Excellent eye! 8', '2005-01-02 21:42:57.000000', NULL, 1),
(1087622, 132245, 22479, '<td valign="top">Selective desat done tastefully...I think it highlights the eternal hope in her eyes. Tonal range is very pleasing in this photo. Good composition overall. 8</td>', 'Selective desat done tastefully...I think it highlights the eternal hope in her eyes. Tonal range is very pleasing in this photo. Good composition overall. 8', '2005-01-02 21:43:07.000000', NULL, 1),
(1087623, 132344, 3306, '<td valign="top">Be careful, some of them can be very slippery! Very good thought provoking picture. You have taken an average scene and made it special. Good job.</td>', 'Be careful, some of them can be very slippery! Very good thought provoking picture. You have taken an average scene and made it special. Good job.', '2005-01-02 21:43:50.000000', NULL, 1),
(1087627, 132288, 22479, '<td valign="top">Lovely. I like the crop the way it is, but I wonder how it would look if you had included more of the peripheral flowers. Image has a dreamy softness to it which is quite pleasing. Well done. 7</td>', 'Lovely. I like the crop the way it is, but I wonder how it would look if you had included more of the peripheral flowers. Image has a dreamy softness to it which is quite pleasing. Well done. 7', '2005-01-02 21:45:00.000000', NULL, 1),
(1087631, 132157, 3306, '<td valign="top">Hopefully the comments are more helpful than bad. I like the way you have created a theme to match your picture. It gives it feeling and purpose. Good job.</td>', 'Hopefully the comments are more helpful than bad. I like the way you have created a theme to match your picture. It gives it feeling and purpose. Good job.', '2005-01-02 21:46:16.000000', NULL, 1),
(1087632, 132221, 22479, '<td valign="top">Creative play on words. Excellent composition and I''m curious how you set this up. I''ll tune in later to read the specifics. 7</td>', 'Creative play on words. Excellent composition and I''m curious how you set this up. I''ll tune in later to read the specifics. 7', '2005-01-02 21:46:49.000000', NULL, 1),
(1087639, 131828, 3306, '<td valign="top">Wow, if you have all those problems I know a good therapist you might want to see!! Kidding aside, very creative and well placed shot. I would definitely pick the toilet seat resolution to work on first. If you can acomplish that, everything else is easy!</td>', 'Wow, if you have all those problems I know a good therapist you might want to see!! Kidding aside, very creative and well placed shot. I would definitely pick the toilet seat resolution to work on first. If you can acomplish that, everything else is easy!', '2005-01-02 21:49:11.000000', NULL, 1),
(1087643, 132435, 3306, '<td valign="top">Is she jumping robe on your head while you do situps!! That IS amazing. Kidding aside, well done picture. I am impressed!</td>', 'Is she jumping robe on your head while you do situps!! That IS amazing. Kidding aside, well done picture. I am impressed!', '2005-01-02 21:51:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1087645, 131810, 3306, '<td valign="top">good title. Makes me hungry to look at it.</td>', 'good title. Makes me hungry to look at it.', '2005-01-02 21:52:20.000000', NULL, 1),
(1087656, 132469, 3306, '<td valign="top">As a father, I can tell you that you could not bring any more joy to your dad than to enjoy his company. That is special. Very good picture and touching title. Good luck.</td>', 'As a father, I can tell you that you could not bring any more joy to your dad than to enjoy his company. That is special. Very good picture and touching title. Good luck.', '2005-01-02 21:56:04.000000', NULL, 1),
(1087660, 132424, 22479, '<td valign="top">Very clever and imaginitive. Technical performance successful and without notable inadequacies. Composition has a distinct symmetry which complements this duet. <br/> <br/>Ultimately, this is not my cup of tea, and if this image survives, I salute you for your bold and daring entry. 7</td>', 'Very clever and imaginitive. Technical performance successful and without notable inadequacies. Composition has a distinct symmetry which complements this duet.  Ultimately, this is not my cup of tea, and if this image survives, I salute you for your bold and daring entry. 7', '2005-01-02 21:58:46.000000', NULL, 1),
(1087661, 131762, 3306, '<td valign="top">Very well done portrait.</td>', 'Very well done portrait.', '2005-01-02 21:58:53.000000', NULL, 1),
(1087751, 132142, 4767, '<td valign="top">GOOD LUCK!</td>', 'GOOD LUCK!', '2005-01-02 22:42:17.000000', NULL, 1),
