(1087758, 132001, 24846, '<td valign="top">Good job evoking the "hiding" feel.  Good luck and HNY.</td>', 'Good job evoking the "hiding" feel.  Good luck and HNY.', '2005-01-02 22:45:21.000000', NULL, 1),
(1087761, 131735, 4767, '<td valign="top">Ah, come on...  NObody can quit eating Cadbury''s, can they?  And if they could, would you want to know them?  THAT kind of people???</td>', 'Ah, come on...  NObody can quit eating Cadbury''s, can they?  And if they could, would you want to know them?  THAT kind of people???', '2005-01-02 22:46:29.000000', NULL, 1),
(1087763, 132084, 24846, '<td valign="top">Nice silhouette and negative space. Good luck and HNY.</td>', 'Nice silhouette and negative space. Good luck and HNY.', '2005-01-02 22:47:04.000000', NULL, 1),
(1087771, 132480, 24846, '<td valign="top">Very vivid. Great capture of the drops. Like the rivery of light in the background. My neck is tired of twisting to decipher the words, look forward to your post description. Good luck with this excellent experimental image and HNY.</td>', 'Very vivid. Great capture of the drops. Like the rivery of light in the background. My neck is tired of twisting to decipher the words, look forward to your post description. Good luck with this excellent experimental image and HNY.', '2005-01-02 22:51:42.000000', NULL, 1),
(1087774, 132274, 24846, '<td valign="top">Lovely capture, would like the beak/head a bit sharper. Good luck and HNY.</td>', 'Lovely capture, would like the beak/head a bit sharper. Good luck and HNY.', '2005-01-02 22:53:24.000000', NULL, 1),
(1087777, 132449, 24846, '<td valign="top">Good idea and setup, a bit blown out lighting. Good luck and HNY.</td>', 'Good idea and setup, a bit blown out lighting. Good luck and HNY.', '2005-01-02 22:54:48.000000', NULL, 1),
(1087785, 132435, 24846, '<td valign="top">A wild mind indeed. Well executed, great lighting, like the choice of grey cast background. Good luck and HNY.</td>', 'A wild mind indeed. Well executed, great lighting, like the choice of grey cast background. Good luck and HNY.', '2005-01-02 22:57:58.000000', NULL, 1),
(1087792, 132283, 24846, '<td valign="top">A smiling child to remind us how to enjoy life. Nice capture, dof, and crop. Good luck and HNY.</td>', 'A smiling child to remind us how to enjoy life. Nice capture, dof, and crop. Good luck and HNY.', '2005-01-02 23:01:41.000000', NULL, 1),
(1087804, 132449, 31213, '<td valign="top">I''m very happy you did not center the path in the pic.  I find it a very inspiring photo!  Some people may complain that the grass is blow out a bit especially toward the back of the photo.  Clever title.</td>', 'I''m very happy you did not center the path in the pic.  I find it a very inspiring photo!  Some people may complain that the grass is blow out a bit especially toward the back of the photo.  Clever title.', '2005-01-02 23:05:18.000000', NULL, 1),
(1087808, 132424, 4767, '<td valign="top">I don''t think of myself as a prude, but this seems in poor taste to me, and seems the antithesis of starting a family.  I am certain that some will see this as humorous and clever, others will snicker at the image.  I think it is making fun of families and I think there are other formats for such sleaze - not DPC.</td>', 'I don''t think of myself as a prude, but this seems in poor taste to me, and seems the antithesis of starting a family.  I am certain that some will see this as humorous and clever, others will snicker at the image.  I think it is making fun of families and I think there are other formats for such sleaze - not DPC.', '2005-01-02 23:06:30.000000', NULL, 1),
(1087835, 132157, 29013, '<td valign="top">try  cropping  about 1/3 off the bottom? see how if you like it?</td>', 'try  cropping  about 1/3 off the bottom? see how if you like it?', '2005-01-02 23:24:48.000000', NULL, 1),
